def _mpl_linestyle2pgfp_linestyle(line_style):
    '''Translates a line style of matplotlib to the corresponding style
    in Pgfplots.
    '''
    line_style_dict = {
        'None': (False, None),
        '-': (True, None),
        ':': (True, 'dotted'),
        '--': (True, 'dashed'),
        '-.': (True, 'dash pattern=on 1pt off 3pt on 3pt off 3pt')
    }

    if line_style in line_style_dict:
        return line_style_dict[line_style]
    else:
        warnings.warn('Unknown line style ''%r''. Using default.' % line_style)
        return True, None
